-- Dated original-factory production events, not estimated lifetime totals.
-- Facts are exact-model, exact-era, official-source and independently audited.
with documented(catalog_model_id,category,label,value,start_year,market,source_name,source_url,scope_note) as (values
(104,'manufacturing_evidence','Multistrada V4 production begins at Borgo Panigale in October 2020','{"date":"2020-10-06","evidence":"Ducati confirmed on 6 October 2020 that Multistrada V4 manufacture was under way at Borgo Panigale ahead of its 4 November public presentation.","factory":"Ducati, Borgo Panigale, Bologna","production_scope":"Original Multistrada V4 production launch; not proof of a fixed lifetime quantity."}'::jsonb,2020,'Borgo Panigale, Italy','Ducati Media House — Multistrada V4 production, 6 October 2020','https://mediahouse.ducati.com/ducati-announces-the-entry-into-production-of-the-world-s-first-motorcycle-equipped-with-front-and-rear-radar-technology-the-new-multistrada-v4-370317/?lang=eng','Original V4, NOT the Multistrada V4 Rally launched in 2023 or the 2020 release of V4 engine details.'),
(102,'manufacturing_evidence','Ducati Monster 937 factory production starts in March 2021','{"date":"2021-03-04","evidence":"Ducati''s 4 March 2021 announcement confirmed new-generation 937 cc Monster assembly had begun at Borgo Panigale, ahead of spring 2021 dealer availability.","factory":"Ducati, Borgo Panigale, Bologna","production_scope":"New 937 cc Testastretta Monster generation only; not the 821 cc Monster or 2025 fifth generation."}'::jsonb,2021,'Borgo Panigale, Italy','Ducati Media House — Production of new Monster begins, 4 March 2021','https://mediahouse.ducati.com/production-of-new-monster-begins-it-s-time-to-have-fun/?lang=eng','Manufacturer factory production milestone, not global retail availability date and not a quantity for Monster 937 alone.'),
(107,'manufacturing_evidence','Original Ducati Panigale V4 production started on 15 November 2017','{"date":"2017-11-15","evidence":"Ducati''s account of the first European dealership deliveries states that original Panigale V4 production began on 15 November 2017.","factory":"Ducati, Borgo Panigale, Bologna","production_scope":"First-generation Panigale V4 production; does not cover Panigale V4 R, Speciale or 2020 updates."}'::jsonb,2017,'Borgo Panigale, Italy','Ducati — Panigale V4, 500 motorcycles delivered, 2018 factory report','https://www.ducati.com/ww/en/editorial/panigale-v4-500-motorcycles-delivered','Report refers to November 15 preceding the 2018 article; model-year and production date are not conflated.')
)
insert into public.motorcycle_catalog_facts(catalog_model_id,category,label,value,start_year,market,source_name,source_url,verification_status)
select d.catalog_model_id,d.category,d.label,d.value,d.start_year,d.market,d.source_name,d.source_url,'verified' from documented d
where exists (select 1 from public.motorcycle_catalog_dropdown_clean m where m.model_id=d.catalog_model_id)
and not exists(select 1 from public.motorcycle_catalog_facts f where f.catalog_model_id=d.catalog_model_id and f.label=d.label and f.source_url=d.source_url);
with documented(catalog_model_id,label,source_url,source_name,scope_note) as (values
(104,'Multistrada V4 production begins at Borgo Panigale in October 2020','https://mediahouse.ducati.com/ducati-announces-the-entry-into-production-of-the-world-s-first-motorcycle-equipped-with-front-and-rear-radar-technology-the-new-multistrada-v4-370317/?lang=eng','Ducati Media House — Multistrada V4 production, 6 October 2020','Original V4, NOT the Multistrada V4 Rally launched in 2023 or the 2020 release of V4 engine details.'),
(102,'Ducati Monster 937 factory production starts in March 2021','https://mediahouse.ducati.com/production-of-new-monster-begins-it-s-time-to-have-fun/?lang=eng','Ducati Media House — Production of new Monster begins, 4 March 2021','Manufacturer factory production milestone, not global retail availability date and not a quantity for Monster 937 alone.'),
(107,'Original Ducati Panigale V4 production started on 15 November 2017','https://www.ducati.com/ww/en/editorial/panigale-v4-500-motorcycles-delivered','Ducati — Panigale V4, 500 motorcycles delivered, 2018 factory report','Report refers to November 15 preceding the 2018 article; model-year and production date are not conflated.')
)
insert into public.motorcycle_catalog_fact_verification_audit(fact_id,checked_at,verification_basis,source_url,scope_note,source_version)
select f.id,now(),'official_factory_production_document_exact_model_reviewed_2026_11_12',d.source_url,d.scope_note,d.source_name
from documented d join public.motorcycle_catalog_facts f on f.catalog_model_id=d.catalog_model_id and f.label=d.label and f.source_url=d.source_url
where not exists(select 1 from public.motorcycle_catalog_fact_verification_audit a where a.fact_id=f.id);
